const updatePublishableKey = `-- name: UpdatePublishableKey :one
UPDATE publishable_keys
SET name = $1, allowed_origins = $2, rate_limits = $3, enabled = $4,
    revision = revision + 1, updated_at = now()
WHERE id = $5
RETURNING id, agent_id, team_id, name, prefix, secret_hash, allowed_origins, rate_limits, enabled, revision, last_used_at, revoked_at, created_by, created_at, updated_at, pepper_id
`

type UpdatePublishableKeyParams struct {
	Name           string
	AllowedOrigins []string
	RateLimits     json.RawMessage
	Enabled        bool
	ID             uuid.UUID
}

func (q *Queries) UpdatePublishableKey(ctx context.Context, arg UpdatePublishableKeyParams) (PublishableKey, error) {
	row := q.db.QueryRow(ctx, updatePublishableKey,
		arg.Name,
		arg.AllowedOrigins,
		arg.RateLimits,
		arg.Enabled,
		arg.ID,
	)
	var i PublishableKey
	err := row.Scan(
		&i.ID,
		&i.AgentID,
		&i.TeamID,
		&i.Name,
		&i.Prefix,
		&i.SecretHash,
		&i.AllowedOrigins,
		&i.RateLimits,
		&i.Enabled,
		&i.Revision,
		&i.LastUsedAt,
		&i.RevokedAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.PepperID,
	)
	return i, err
}
